"use client";

/**
 * Skeleton build: a product screen assembles itself. Loading blocks grow in
 * reading order with a soft shimmer, then each block resolves in place into
 * the real element: text settles in, bars rise, figures count up. The shot
 * holds on the finished screen with a slow push in.
 *
 * Written by Better Design. Painted from the theme prop: the blocks are the
 * theme's muted colour, and the finished screen uses its card, ink and primary.
 */
import type { ReactNode } from "react";
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, type SoundCue, SoundTrack, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

/** Timing, in frames: blocks grow in from GROW_AT, resolve from RESOLVE_AT, and the camera pushes from PUSH_AT. */
const GROW_AT = 6;
const GROW_STEP = 1.1;
const GROW_FRAMES = 12;
const RESOLVE_AT = 52;
const RESOLVE_STEP = 1.4;
const RESOLVE_FRAMES = 12;
const PUSH_AT = 100;
const SHIMMER_FRAMES = 36;

/** The sound of a SkeletonBuild: air as the blocks grow in, then a shimmer as they resolve into the real screen. */
export const skeletonBuildCues = (): SoundCue[] => [
  { sfx: "whoosh-long", at: GROW_AT + 14, gain: -5 },
  { sfx: "shimmer", at: RESOLVE_AT + 4 },
];

/** One headline figure on the screen. */
export interface SkeletonMetric {
  label: string;
  value: number;
  /** Appended to the counted figure, such as "%" or "k". */
  unit?: string;
}

/** One row of the list card. */
export interface SkeletonRow {
  name: string;
  detail: string;
  status: string;
}

export interface SkeletonBuildProps {
  /** The product name in the sidebar. */
  appName?: string;
  heading?: string;
  /** The label of the primary button in the header. */
  action?: string;
  navigation?: string[];
  /** Up to three figures across the top. */
  metrics?: SkeletonMetric[];
  chartTitle?: string;
  /** One value per bar, scaled against the largest. */
  bars?: number[];
  listTitle?: string;
  rows?: SkeletonRow[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
  /** Play the shot's own sound cues. Leave off inside a film that plays every scene's cues in one SoundTrack. */
  sound?: boolean;
}

interface BlockTiming {
  frame: number;
  theme: VideoTheme;
}

/** How far a block has grown in and resolved, from its place in the reading order. */
function stateOf(order: number, frame: number) {
  return {
    grown: easings.out(progress(frame, GROW_AT + order * GROW_STEP, GROW_FRAMES)),
    resolved: easings.out(progress(frame, RESOLVE_AT + order * RESOLVE_STEP, RESOLVE_FRAMES)),
  };
}

/**
 * One element of the screen with its loading block laid exactly over it. The
 * block takes the element's own box, so the skeleton is the finished layout.
 */
function Block({ order, timing, round = 8, display = "block", children }: { order: number; timing: BlockTiming; round?: number; display?: "block" | "inline-block" | "flex"; children: ReactNode }) {
  const { frame, theme } = timing;
  const { grown, resolved } = stateOf(order, frame);
  // The shimmer is one band that crosses every block at the same moment, so the screen reads as one surface loading.
  const sweep = ((frame % SHIMMER_FRAMES) / SHIMMER_FRAMES) * 160 - 30;
  return (
    <div style={{ position: "relative", display }}>
      <div style={{ opacity: resolved, transform: `translateY(${(1 - resolved) * 8}px)` }}>{children}</div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: round,
          background: `linear-gradient(100deg, ${withAlpha(theme.foreground, 0.08)} ${sweep - 20}%, ${withAlpha(theme.foreground, 0.03)} ${sweep}%, ${withAlpha(theme.foreground, 0.08)} ${sweep + 20}%)`,
          transformOrigin: "left center",
          transform: `scaleX(${grown})`,
          opacity: grown * (1 - resolved),
        }}
      />
    </div>
  );
}

const DEFAULT_METRICS: SkeletonMetric[] = [
  { label: "Active teams", value: 1284 },
  { label: "Films rendered", value: 9420 },
  { label: "On-brand score", value: 97, unit: "%" },
];
const DEFAULT_ROWS: SkeletonRow[] = [
  { name: "Launch film", detail: "Rendered 2 minutes ago", status: "Ready" },
  { name: "Changelog, week 41", detail: "Rendering frame 212 of 360", status: "Rendering" },
  { name: "Onboarding tour", detail: "Edited by the agent", status: "Draft" },
];

/** A product screen that builds itself from loading blocks into the finished interface. */
export function SkeletonBuild({
  appName = "Northwind",
  heading = "Overview",
  action = "New film",
  navigation = ["Overview", "Films", "Brand", "Team", "Settings"],
  metrics = DEFAULT_METRICS,
  chartTitle = "Films this week",
  bars = [38, 52, 46, 70, 61, 84, 76],
  listTitle = "Recent",
  rows = DEFAULT_ROWS,
  theme: themeOverride,
  font,
  sound = false,
}: SkeletonBuildProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const timing: BlockTiming = { frame, theme };

  // Reading order: the sidebar top to bottom, then the header, figures, chart and list.
  let order = 0;
  const next = () => order++;
  const radius = theme.radius;
  const push = 1 + 0.035 * easings.inOut(progress(frame, PUSH_AT, 50));
  const enter = easings.out(progress(frame, 0, 12));
  const tallest = Math.max(...bars, 1);
  const card = { background: theme.card, border: `1px solid ${theme.border}`, borderRadius: radius * 1.5, padding: 32 };
  const text = (size: number, weight: number, color = theme.foreground) => ({ fontSize: size, fontWeight: weight, color, lineHeight: 1.2 });

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      {sound ? <SoundTrack cues={skeletonBuildCues()} music={false} /> : null}
      <div
        style={{
          width: 1600,
          height: 900,
          display: "flex",
          background: theme.background,
          border: `1px solid ${theme.border}`,
          borderRadius: radius * 2,
          overflow: "hidden",
          boxShadow: `0 50px 120px -60px ${withAlpha(theme.foreground, 0.35)}`,
          opacity: enter,
          transform: `scale(${push})`,
        }}
      >
        <aside style={{ width: 300, padding: 32, borderRight: `1px solid ${theme.border}`, background: theme.muted, display: "flex", flexDirection: "column", gap: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 26 }}>
            <Block order={next()} timing={timing} round={12}>
              <div style={{ width: 44, height: 44, borderRadius: 12, background: theme.primary }} />
            </Block>
            <Block order={next()} timing={timing} display="inline-block">
              <span style={text(26, 700)}>{appName}</span>
            </Block>
          </div>
          {navigation.map((item, i) => (
            <Block key={item} order={next()} timing={timing} round={10}>
              <div style={{ padding: "12px 16px", borderRadius: 10, background: i === 0 ? theme.card : "transparent", ...text(22, i === 0 ? 600 : 500, i === 0 ? theme.foreground : theme.mutedForeground) }}>{item}</div>
            </Block>
          ))}
        </aside>
        <main style={{ flex: 1, padding: 40, display: "flex", flexDirection: "column", gap: 28 }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <Block order={next()} timing={timing} display="inline-block">
              <span style={text(44, 700)}>{heading}</span>
            </Block>
            <Block order={next()} timing={timing} round={999} display="inline-block">
              <div style={{ padding: "14px 26px", borderRadius: 999, background: theme.primary, ...text(22, 600, theme.primaryForeground) }}>{action}</div>
            </Block>
          </div>
          <div style={{ display: "flex", gap: 24 }}>
            {metrics.slice(0, 3).map((metric) => {
              const labelOrder = next();
              const valueOrder = next();
              const counted = metric.value * easings.out(progress(frame, RESOLVE_AT + valueOrder * RESOLVE_STEP, 30));
              return (
                <div key={metric.label} style={{ ...card, flex: 1, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 14 }}>
                  <Block order={labelOrder} timing={timing} display="inline-block">
                    <span style={text(20, 500, theme.mutedForeground)}>{metric.label}</span>
                  </Block>
                  <Block order={valueOrder} timing={timing} display="inline-block">
                    {/* The final figure sets the width, so the count never resizes its block. */}
                    <span style={{ ...text(46, 700), fontVariantNumeric: "tabular-nums", position: "relative", display: "inline-block" }}>
                      <span style={{ visibility: "hidden" }}>{`${metric.value.toLocaleString("en-US")}${metric.unit ?? ""}`}</span>
                      <span style={{ position: "absolute", left: 0, top: 0 }}>{`${Math.round(counted).toLocaleString("en-US")}${metric.unit ?? ""}`}</span>
                    </span>
                  </Block>
                </div>
              );
            })}
          </div>
          <div style={{ flex: 1, display: "flex", gap: 24, minHeight: 0 }}>
            <div style={{ ...card, flex: 1.3, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 20 }}>
              <Block order={next()} timing={timing} display="inline-block">
                <span style={text(24, 600)}>{chartTitle}</span>
              </Block>
              <div style={{ flex: 1, alignSelf: "stretch", display: "flex", alignItems: "flex-end", gap: 18, borderBottom: `1px solid ${theme.border}` }}>
                {bars.map((value, i) => {
                  const barOrder = next();
                  const { grown, resolved } = stateOf(barOrder, frame);
                  // A bar waits at a placeholder height, then rises to its value as it resolves.
                  const share = 0.35 + (value / tallest - 0.35) * resolved;
                  const isLast = value === tallest;
                  return (
                    <div
                      key={i}
                      style={{
                        flex: 1,
                        height: `${share * 100}%`,
                        borderRadius: 10,
                        transformOrigin: "bottom",
                        transform: `scaleY(${grown})`,
                        background: mix(mix(theme.card, theme.foreground, 0.08), isLast ? theme.primary : mix(theme.card, theme.primary, 0.24), resolved),
                      }}
                    />
                  );
                })}
              </div>
            </div>
            <div style={{ ...card, flex: 1, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 22 }}>
              <Block order={next()} timing={timing} display="inline-block">
                <span style={text(24, 600)}>{listTitle}</span>
              </Block>
              {rows.map((row) => (
                <div key={row.name} style={{ alignSelf: "stretch", display: "flex", alignItems: "center", gap: 16 }}>
                  <Block order={next()} timing={timing} round={14}>
                    <div style={{ width: 52, height: 52, borderRadius: 14, background: withAlpha(theme.primary, 0.16), display: "flex", alignItems: "center", justifyContent: "center", ...text(22, 700, theme.primary) }}>
                      {row.name.slice(0, 1)}
                    </div>
                  </Block>
                  <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 8, minWidth: 0 }}>
                    <Block order={next()} timing={timing} display="inline-block">
                      <span style={text(21, 600)}>{row.name}</span>
                    </Block>
                    <Block order={next()} timing={timing} display="inline-block">
                      <span style={text(17, 500, theme.mutedForeground)}>{row.detail}</span>
                    </Block>
                  </div>
                  <Block order={next()} timing={timing} round={999} display="inline-block">
                    <span style={{ padding: "8px 16px", borderRadius: 999, background: theme.accent, ...text(17, 600, theme.accentForeground) }}>{row.status}</span>
                  </Block>
                </div>
              ))}
            </div>
          </div>
        </main>
      </div>
    </AbsoluteFill>
  );
}
